import { mapState } from "vuex";
import printJS from "print-js";
import {
  getExpressData,
  putDelivery,
  splitDelivery,
  orderExpressTemp,
  orderDeliveryList,
  orderSheetInfo,
  splitCartInfo,
  orderBusinessApi,
  orderPriceApi,
} from "@/api/order";

export default {
  name: "orderSend",
  props: {
    orderId: Number,
    status: Number,
    pay_type: String,
  },
  data() {
    return {
      productType: 0,
      orderStatus: 0,
      splitSwitch: false,
      formItem: {
        type: "1",
        express_record_type: "1",
        delivery_name: "",
        delivery_id: "",
        express_temp_id: "",
        to_name: "",
        to_tel: "",
        to_addr: "",
        sh_delivery: "",
        fictitious_content: "",
        station_type: 1,
        delivery_type: "1",
        cargo_weight: 0,
        remark: "",
        mark: "",
        server_type: "",
        day_type: 0,
        pickup_time: ["", ""],
      },
      modals: false,
      express: [],
      expressTemp: [],
      deliveryList: [],
      temp: {
        pic:''
      },
      export_open: true,
      manyFormValidate: [],
      stopSubmit: false,
      header: [
        {
          type: "selection",
          width: 60,
          align: "center",
        },
        {
          title: "商品信息",
          slot: "image",
          width: 200,
          align: "center",
        },
        {
          title: "规格",
          slot: "value",
          align: "center",
          minWidth: 120,
        },
        {
          title: "商品售价",
          slot: "sellPrice",
          align: "center",
          minWidth: 100,
        },
        {
          title: "商品优惠价",
          slot: "price",
          align: "center",
          minWidth: 100,
        },
        {
          title: "总数",
          key: "cart_num",
          align: "center",
          minWidth: 80,
        },
        {
          title: "待发数量",
          key: "surplus_num",
          align: "center",
          width: 180,
          render: (h, params) => {
            return h("div", [
              h("InputNumber", {
                props: {
                  min: 1,
                  max: params.row.numShow,
                  value: params.row.surplus_num || 1,
                },
                on: {
                  "on-change": (e) => {
                    params.row.surplus_num = e || 1;
                    this.manyFormValidate[params.index] = params.row;
                    this.selectData.forEach((v, index) => {
                      if (v.cart_id === params.row.cart_id) {
                        this.selectData.splice(index, 1, params.row);
                      }
                    });
                  },
                },
              }),
            ]);
          },
        },
      ],
      selectData: [],
      sheetInfo: {},
      serviceTypeList: [],
      kuaidiExpress: [],
      sendPrice: 0,
    };
  },
  computed: {
    ...mapState("admin/order", ["splitOrder"]),
  },
  methods: {
    printImg(url) {
      printJS({
        printable: url,
        type: "image",
        documentTitle: "快递信息",
        style: `img{
          width: 100%;
          height: 476px;
        }`,
      });
    },
    changeDelivery(e) {
      // console.log('eeeeeeeee',e);
      // this.formItem.delivery_type = e;
    },
    selectOne(data) {
      this.selectData = data;
    },
    changeModal(status) {
      if (!status) this.cancel();
    },
    changeSplitStatus(status) {
      if (status) {
        splitCartInfo(this.orderId).then((res) => {
          let data = res.data;
          data.forEach((item) => {
            item.numShow = item.surplus_num;
          });
          this.manyFormValidate = data;
        });
      }
    },
    changeRadio(o) {
      this.$refs.formItem.resetFields();
      switch (o) {
        case "1":
          this.formItem.delivery_name = "";
          this.formItem.delivery_id = "";
          this.formItem.express_temp_id = "";
          this.formItem.express_record_type = "1";
          this.expressTemp = [];
          break;
        case "2":
          this.formItem.sh_delivery = "";
          if (this.sheetInfo.self_delivery_status) {
            this.formItem.delivery_type = "1";
          } else {
            this.formItem.delivery_type = "2";
          }
          if (this.sheetInfo.dada_delivery_status) {
            this.formItem.station_type = 1;
          } else {
            this.formItem.station_type = 2;
          }
          break;
        case "3":
          this.formItem.fictitious_content = "";
          break;
        default:
          break;
      }
    },
    changeExpress(j) {
      switch (j) {
        case "2":
          this.formItem.delivery_name = "";
          this.formItem.express_temp_id = "";
          this.expressTemp = [];
          this.getList(2);
          break;
        case "1":
          this.formItem.delivery_name = "";
          this.formItem.delivery_id = "";
          this.getList(1);
          break;
        default:
          break;
      }
    },
    reset() {
      this.formItem = {
        type: "1",
        express_record_type: "1",
        delivery_name: "",
        delivery_id: "",
        express_temp_id: "",
        to_name: "",
        to_tel: "",
        to_addr: "",
        sh_delivery: "",
        fictitious_content: "",
        station_type: 1,
        delivery_type: "1",
        cargo_weight: 0,
        remark: "",
        mark: "",
        server_type: "",
        day_type: 0,
        pickup_time: ["", ""],
      };
      this.sendPrice = 0;
    },
    // 物流公司列表
    getList(type) {
      let status = type === 2 ? 1 : "";
      getExpressData(status)
        .then(async (res) => {
          this.express = res.data;
          this.getSheetInfo();
        })
        .catch((res) => {
          this.loading = false;
          this.$Message.error(res.msg);
        });
    },
    // 提交
    putSend(name) {
      let data = {
        id: this.orderId,
        datas: this.formItem,
      };
      if (
        this.formItem.type === "1" &&
        this.formItem.express_record_type === "2"
      ) {
        if (this.formItem.delivery_name === "") {
          return this.$Message.error("快递公司不能为空");
        } else if (this.formItem.express_temp_id === "") {
          return this.$Message.error("电子面单不能为空");
        } else if (this.formItem.to_name === "") {
          return this.$Message.error("寄件人姓名不能为空");
        } else if (this.formItem.to_tel === "") {
          return this.$Message.error("寄件人电话不能为空");
        } else if (!/^1(3|4|5|7|8|9|6)\d{9}$/i.test(this.formItem.to_tel)) {
          return this.$Message.error("请输入正确的手机号码");
        } else if (this.formItem.to_addr === "") {
          return this.$Message.error("寄件人地址不能为空");
        }
      }
      if (
        this.formItem.type === "1" &&
        this.formItem.express_record_type === "1"
      ) {
        if (this.formItem.delivery_name === "") {
          return this.$Message.error("快递公司不能为空");
        } else if (this.formItem.delivery_id === "") {
          return this.$Message.error("快递单号不能为空");
        }
      }
      if (this.formItem.type === "2") {
        if (
          this.formItem.delivery_type === "1" &&
          this.formItem.sh_delivery === ""
        ) {
          return this.$Message.error("送货人不能为空");
        }
        if (
          this.formItem.delivery_type === "2" &&
          this.formItem.cargo_weight <= 0
        ) {
          return this.$Message.error("请输入有效的重量");
        }
      }
      if (this.splitSwitch) {
        data.datas.cart_ids = [];
        this.selectData.forEach((v) => {
          data.datas.cart_ids.push({
            cart_id: v.cart_id,
            cart_num: v.surplus_num,
          });
        });
        splitDelivery(data)
          .then((res) => {
            this.modals = false;
            this.$Message.success(res.msg);
            this.$emit("submitFail");
            this.reset();
            this.splitSwitch = false;
            //修改增加打印机打印
            if (res.data.dump.label) this.printImg(res.data.dump.label);
          })
          .catch((res) => {
            this.$Message.error(res.msg);
          });
      } else {
        putDelivery(data)
          .then(async (res) => {
            this.modals = false;
            this.$Message.success(res.msg);
            this.splitSwitch = false;
            this.$emit("submitFail");
            this.reset();
            //修改增加打印机打印
            if (res.data.dump.label) this.printImg(res.data.dump.label);
          })
          .catch((res) => {
            this.$Message.error(res.msg);
          });
      }
    },
    cancel(name) {
      this.modals = false;
      this.orderStatus = 0;
      this.splitSwitch = false;
      this.selectData = [];
      this.reset();
    },
    // 电子面单列表
    expressChange(value) {
      this.formItem.service_type = "";
      let expressItem = (this.formItem.express_record_type == "3"
        ? this.kuaidiExpress
        : this.express
      ).find((item) => {
        return item.value === value;
      });
      if (expressItem === undefined) {
        return;
      }
      this.serviceTypeList = expressItem.types;
      if (this.formItem.type == 1 && this.formItem.express_record_type == 3) {
        this.formItem.service_type = expressItem.types.length
          ? expressItem.types[0]
          : "";
      }
      this.formItem.delivery_code = expressItem.code;
      if (
        this.formItem.to_name &&
        this.formItem.to_addr &&
        this.formItem.express_record_type == 3
      )
        this.watchPrice();
      if (this.formItem.express_record_type === "2") {
        this.expressTemp = [];
        this.formItem.express_temp_id = "";
        orderExpressTemp({
          com: this.formItem.delivery_code,
        })
          .then((res) => {
            this.expressTemp = res.data;
            this.formItem.express_temp_id = res.data.length ? res.data[0].temp_id: "";
            this.temp = this.expressTemp[0];
            if (!res.data.length) {
              this.$Message.error("请配置你所选快递公司的电子面单");
            }
          })
          .catch((err) => {
            this.$Message.error(err.msg);
          });
      } else if (this.formItem.express_record_type == "3") {
        this.expressTemp = expressItem.list;
        if (expressItem.list.length) {
          this.formItem.express_temp_id = expressItem.list[0].temp_id;
          this.temp = expressItem.list[0];
          console.log(expressItem.list[0], "expressItem.list[0]");
        }
      }
    },
    watchPrice() {
      if (this.formItem.express_record_type != 3) return;
      let data = {
        kuaidicom: this.formItem.delivery_code,
        send_address: this.formItem.to_addr,
        orderId: this.orderId,
        service_type: this.formItem.service_type,
        cart_ids: [],
      };
      this.selectData.forEach((v) => {
        data.cart_ids.push({
          cart_id: v.cart_id,
          cart_num: v.num || v.surplus_num,
        });
      });
      orderPriceApi(data)
        .then((res) => {
          this.sendPrice = res.data.price;
          this.deliveryErrorMsg = "";
        })
        .catch((err) => {
          this.$Message.error(err.msg);
          if (this.formItem.type == 1) {
            this.deliveryErrorMsg = err.msg;
          }
        });
    },
    getCartInfo() {
      // this.$set(this, "orderStatus", data);
      // this.$set(this, "splitSwitch", data === 8 ? true : false);
      // if (data === 8) {
      splitCartInfo(this.orderId).then((res) => {
        let data = res.data;
        data.forEach((item) => {
          item.numShow = item.surplus_num;
        });
        this.manyFormValidate = data;
        this.productType = data[0].product_type;
        if (this.productType == 3) {
          this.formItem.type = "3";
          this.formItem.fictitious_content = "";
        }
      });
    },
    getDeliveryList() {
      orderDeliveryList()
        .then((res) => {
          this.deliveryList = res.data.list;
        })
        .catch((err) => {
          this.$Message.error(err.msg);
        });
    },
    getSheetInfo() {
      orderSheetInfo()
        .then((res) => {
          const data = res.data;
          for (const key in data) {
            if (data.hasOwnProperty(key)) {
              this.formItem[key] = data[key];
            }
          }
          this.export_open =
            data.export_open === undefined ? true : data.export_open;
          if (!this.export_open) {
            this.formItem.express_record_type = "1";
          }
          this.formItem.to_addr = data.to_add;
          this.sheetInfo = data;
        })
        .catch((err) => {
          this.$Message.error(err.msg);
        });
    },
    shDeliveryChange(value) {
      if (!value) return;
      let deliveryItem = this.deliveryList.find((item) => {
        return item.id === value;
      });
      this.formItem.sh_delivery_name = deliveryItem.wx_name;
      this.formItem.sh_delivery_id = deliveryItem.phone;
      this.formItem.sh_delivery_uid = deliveryItem.uid;
    },
    expressTempChange(tempId) {
      this.temp = this.expressTemp.find((item) => {
        return tempId === item.temp_id;
      });
      if (this.temp === undefined) {
        this.temp = {};
      }
      console.log(this.temp,'lll');
    },
    preview() {
      console.log(this.temp);
      if(!this.temp.pic) return this.$Message.warning('请先选择物流公司或者电子面单');
      this.$refs.viewer.$viewer.show();
    },
    getBusineseList() {
      orderBusinessApi().then((res) => {
        this.kuaidiExpress = res.data;
        if (this.formItem.delivery_name)
          this.expressChange(this.formItem.delivery_name);
      });
    },
  },
};
